<script setup lang="ts">import{onMounted,onBeforeUnmount,useTemplateRef,shallowRef}from'vue';const root=useTemplateRef<HTMLElement>('root');const shown=shallowRef(false);let observer:IntersectionObserver|undefined;onMounted(()=>{if(matchMedia('(prefers-reduced-motion: reduce)').matches){shown.value=true;return}observer=new IntersectionObserver(([entry])=>{if(entry?.isIntersecting){shown.value=true;observer?.disconnect()}},{threshold:.12});if(root.value)observer.observe(root.value)});onBeforeUnmount(()=>observer?.disconnect())</script>
<template><div ref="root" class="reveal" :class="{shown}"><slot/></div></template>
<style scoped>.reveal{opacity:0;transform:translateY(32px);transition:opacity .7s var(--ease),transform .7s var(--ease)}.shown{opacity:1;transform:none}@media(prefers-reduced-motion:reduce){.reveal{opacity:1;transform:none;transition:none}}</style>
